// Appendix A, one item per section / FAQ (n8n/src/handbook.cjs). Re-running is safe:
// the previous step deletes this source first, so there are no duplicates.
const sections = [
  {
    "section": "1. Работно време и контакти",
    "text": "Поддръжката работи от понеделник до петък, 09:00–18:00. На запитвания, получени извън работно време, се отговаря в следващия работен ден. Целево време за първи отговор: 1 работен ден; за спешни случаи: 4 работни часа. Телефон: +359 2 000 0000 (измислен). Имейл: support@hometech.example."
  },
  {
    "section": "2. Доставка",
    "text": "Поръчките се изпращат до 1 работен ден. Доставката в България отнема 1–2 работни дни, в други държави от ЕС – 3–6 работни дни. Всяка поръчка получава номер за проследяване по имейл при изпращането. Ако пратката не е мърдала 5 работни дни, клиентът трябва да се свърже с поддръжката с номера на поръчката; тогава отваряме проверка с куриера, която отнема до 7 работни дни. Доставката е безплатна за поръчки над €50; иначе струва €4.90."
  },
  {
    "section": "3. Връщане на стока и пари",
    "text": "Клиентът може да върне всеки продукт до 30 дни от датата на покупка без да посочва причина, ако продуктът е комплектен и неповреден. За да започне връщане, клиентът отговаря на имейла от поддръжката с номера на поръчката; ние изпращаме предплатен етикет за връщане. Парите се възстановяват по оригиналния начин на плащане в рамките на 5–7 работни дни след като върнатият продукт пристигне в склада ни. Таксата за доставка не се възстановява, освен ако продуктът е бил дефектен."
  },
  {
    "section": "4. Гаранция",
    "text": "Всички продукти имат 24-месечна гаранция от датата на покупка. Гаранцията покрива производствени дефекти. Тя не покрива физически повреди (изпускане, пукнатини), повреди от вода или от отваряне на устройството. Гаранционните случаи се проверяват от сервизния ни екип до 10 работни дни; продуктът се ремонтира или заменя. След изтичане на гаранцията предлагаме платен ремонт: таксата за диагностика е €15 и се приспада от цената на ремонта, ако клиентът го приеме."
  },
  {
    "section": "5. Фактури",
    "text": "Фактура се изпраща автоматично по имейл с всяка поръчка. За фирмена фактура при поръчката се въвеждат име на фирмата и ДДС номер; фактурите не могат да се променят по-късно от 5 дни след датата на покупка. Клиентът може да поиска копие на фактура от поддръжката по всяко време."
  },
  {
    "section": "6. ЧЗВ: HT Thermo 2 показва „No Wi-Fi“",
    "text": "HT Thermo 2 (смарт термостат) показва „No Wi-Fi“: термостатът работи само с Wi-Fi мрежи на 2.4 GHz. Проверете дали рутерът излъчва мрежа на 2.4 GHz, след това задръжте бутона за меню 10 секунди, за да рестартирате настройката на Wi-Fi."
  },
  {
    "section": "6. ЧЗВ: HT Cam Outdoor е offline",
    "text": "HT Cam Outdoor е offline в приложението: проверете захранващия адаптер, след това приближете рутера или добавете Wi-Fi усилвател; камерата има нужда от сигнал поне 2 чертички. Ако остане offline, натиснете бутона за reset за 15 секунди и добавете камерата отново в приложението."
  },
  {
    "section": "6. ЧЗВ: HT Plug Mini не се сдвоява",
    "text": "HT Plug Mini не се сдвоява: контактът трябва да е в режим на сдвояване (светодиодът мига бързо). Задръжте бутона 6 секунди, докато светодиодът започне да мига бързо, и добавете устройството в приложението до 3 минути."
  },
  {
    "section": "6. ЧЗВ: Фърмуер на HT Hub",
    "text": "Фърмуер на HT Hub: обновленията се инсталират автоматично през нощта между 02:00 и 04:00. По време на обновление устройствата може да са недостъпни до 5 минути."
  },
  {
    "section": "7. Тон на комуникация",
    "text": "Отговорите са приятелски, кратки (до 150 думи) и на езика на клиента. Обръщаме се към клиента с малкото му име. Никога не обещаваме нещо, което го няма в този наръчник (напр. отстъпки, по-бърза доставка или изключения от срока за връщане). Подпис: „Екипът по поддръжка на HomeTech“."
  }
];
return sections.map((s) => ({ json: s }));
